{"name":"Write","arguments":{"content":"# loadsheet.ps1 -- freight load-sheet helpers for the northbound runs.

# Dot-source this file, then:

#   $rows = @(Read-LoadRows -Path loads.csv)
#   Format-LoadSheet -Rows $rows -Title 'northbound am'

# loads.csv columns: id,dest,kg,pri   (kg/pri integers)

Set-StrictMode -Version Latest

function Read-LoadRows {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "file not found: $Path"
    }
    $leaf = Split-Path -Leaf $Path
    $rows = @()
    $line = 1   # the header sits on line 1
    foreach ($rec in @(Import-Csv -LiteralPath $Path)) {
        $line++
        if ([string]::IsNullOrEmpty($rec.id)) {
            throw "${leaf}: bad row $line"
        }
        $kg = 0
        $pri = 0
        if (-not [int]::TryParse($rec.kg, [ref]$kg) -or
            -not [int]::TryParse($rec.pri, [ref]$pri)) {
            throw "${leaf}: bad row $line"
        }
        $rows += [pscustomobject]@{
            Id = $rec.id
            Dest = $rec.dest
            Kg = [int]$kg
            Pri = [int]$pri
        }
    }
    return $rows
}

function Select-HeavyLoads {
    param(
        [Parameter(ValueFromPipeline)][object[]]$InputObject,
        [object[]]$Rows,
        [Parameter(Mandatory)][int]$MinKg
    )
    $data = if ($Rows) { $Rows } else { $InputObject }
    $out = @()
    foreach ($load in $data) {
        if ([int]$load.Kg -ge $MinKg) {
            $out += $load
        }
    }
    return $out
}

function Select-Destination {
    param(
        [Parameter(ValueFromPipeline)][object[]]$InputObject,
        [object[]]$Rows,
        [Parameter(Mandatory)][string]$Dest
    )
    $data = if ($Rows) { $Rows } else { $InputObject }
    $out = @()
    foreach ($load in $data) {
        if ($load.Dest -ceq $Dest) {
            $out += $load
        }
    }
    return $out
}

function Measure-Loads {
    param(
        [Parameter(ValueFromPipeline)][object[]]$InputObject,
        [object[]]$Rows
    )
    $data = if ($Rows) { $Rows } else { $InputObject }
    $count = 0
    $total = 0
    $max = 0
    foreach ($load in $data) {
        $kg = [int]$load.Kg
        $count++
        $total += $kg
        if ($kg -gt $max) { $max = $kg }
    }
    return [pscustomobject]@{
        Count = $count
        TotalKg = $total
        MaxKg = $max
    }
}

function Format-LoadSheet {
    param(
        [Parameter(ValueFromPipeline)][object[]]$InputObject,
        [object[]]$Rows,
        [Parameter(Mandatory)][string]$Title
    )
    $data = if ($Rows) { $Rows } else { $InputObject }
    $lines = @("LOAD SHEET: $Title")
    if ($null -eq $data -or $data.Count -eq 0) {
        $lines += 'no loads'
        return (($lines -join "`n") + "`n")
    }
    $lines += ('id'.PadRight(10) + 'dest'.PadRight(20) + 'kg'.PadLeft(6) + 'pri'.PadLeft(5))
    foreach ($load in $data) {
        $lines += ($load.Id.PadRight(10) + $load.Dest.PadRight(20) +
                   $load.Kg.ToString().PadLeft(6) + $load.Pri.ToString().PadLeft(5))
    }
    $summary = Measure-Loads -Rows $data
    $lines += "total $($summary.Count) loads, $($summary.TotalKg) kg"
    return (($lines -join "`n") + "`n")
}
","file_path":"loadsheet.ps1"}}

{"name":"Write","arguments":{"content":"# loadsheet.ps1 -- freight load-sheet helpers for the northbound runs.
#
# Dot-source this file, then:
#
#   $rows = @(Read-LoadRows -Path loads.csv)
#   Format-LoadSheet -Rows $rows -Title 'northbound am'
#
# loads.csv columns: id,dest,kg,pri   (kg/pri integers)
#
# Loads travel between functions as records with Id/Dest ([string]) and
# Kg/Pri ([int]) properties. Every helper takes them via -Rows or the
# pipeline; the two spellings behave identically.

Set-StrictMode -Version Latest

function Read-LoadRows {
    # Parse the dispatch CSV into load records, file order preserved.
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "file not found: $Path"
    }
    $leaf = Split-Path -Leaf $Path
    $rows = @()
    $line = 1   # the header sits on line 1
    foreach ($rec in @(Import-Csv -LiteralPath $Path)) {
        $line++
        $kg = 0
        $pri = 0
        if ([string]::IsNullOrEmpty($rec.id) -or
            -not [int]::TryParse($rec.kg, [ref]$kg) -or
            -not [int]::TryParse($rec.pri, [ref]$pri)) {
            throw "${leaf}: bad row $line"
        }
        $rows += [pscustomobject]@{
            Id   = [string]$rec.id
            Dest = [string]$rec.dest
            Kg   = $kg
            Pri  = $pri
        }
    }
    return $rows
}

function Select-HeavyLoads {
    # Keep the loads at or above the weight cutoff.
    param(
        [Parameter(ValueFromPipeline)][psobject[]]$Rows = @(),
        [Parameter(Mandatory)][int]$MinKg
    )
    process {
        foreach ($row in @($Rows)) {
            if ($row.Kg -ge $MinKg) { $row }
        }
    }
}

function Select-Destination {
    # Keep the loads bound for one destination (exact, case-sensitive).
    param(
        [Parameter(ValueFromPipeline)][psobject[]]$Rows = @(),
        [Parameter(Mandatory)][string]$Dest
    )
    process {
        foreach ($row in @($Rows)) {
            if ($row.Dest -ceq $Dest) { $row }
        }
    }
}

function Measure-Loads {
    # Totals for a set of loads: one record with Count, TotalKg, MaxKg.
    param([Parameter(ValueFromPipeline)][psobject[]]$Rows = @())
    begin {
        $count = 0
        $total = 0
        $max = 0
    }
    process {
        foreach ($row in @($Rows)) {
            $count++
            $total += $row.Kg
            if ($row.Kg -gt $max) { $max = $row.Kg }
        }
    }
    end {
        [pscustomobject]@{
            Count   = [int]$count
            TotalKg = [int]$total
            MaxKg   = [int]$max
        }
    }
}

function Format-LoadSheet {
    # Render the printable sheet the yard crew works from. Returns one
    # string; the caller decides where it goes.
    param(
        [Parameter(ValueFromPipeline)][psobject[]]$Rows = @(),
        [Parameter(Mandatory)][string]$Title
    )
    begin { $all = @() }
    process {
        if ($null -ne $Rows) { $all += @($Rows) }
    }
    end {
        $lines = @("LOAD SHEET: $Title")
        if ($all.Count -eq 0) {
            $lines += 'no loads'
            return (($lines -join "`n") + "`n")
        }
        $lines += ('id'.PadRight(10) + 'dest'.PadRight(20) + 'kg'.PadLeft(6) + 'pri'.PadLeft(5))
        foreach ($row in $all) {
            $lines += ($row.Id.PadRight(10) + $row.Dest.PadRight(20) +
                       ([string]$row.Kg).PadLeft(6) + ([string]$row.Pri).PadLeft(5))
        }
        $summary = Measure-Loads -Rows $all
        $lines += "total $($summary.Count) loads, $($summary.TotalKg) kg"
        return (($lines -join "`n") + "`n")
    }
}
