def compile_plan(text):
    data = yaml.safe_load(text)
    do_block = data.get('do')
    if do_block is None:
        return {"tasks": []}
    plan_dict, _ = compile_block(do_block)
    return plan_dict

def compile_block(block_tasks):
    entries = []
    name_to_index = {}
    for i, task_item in enumerate(block_tasks):
        if len(task_item) != 1:
            task_name = list(task_item.keys())[0]
            task_content = task_item[task_name]
        else:
            task_name, task_content = next(iter(task_item.items()))
        name_to_index[task_name] = i
        known_types = {'call', 'run', 'set', 'switch', 'for', 'raise', 'emit', 'wait'}
        task_type = None
        for key in task_content:
            if key in known_types:
                task_type = key
                break
        if task_type is None:
            raise ValueError(f"No known task type in task content: {task_content}")
        spec = task_content[task_type]
        then_target = task_content.get('then', 'continue')
        entry = {
            'index': i,
            'name': task_name,
            'type': task_type,
            'next': None,
        }
        if task_type == 'switch':
            cases = []
            for case in spec:
                when = case.get('when', None)
                case_then = case.get('then', 'continue')
                cases.append({'when': when, 'then': case_then})
            entry['cases'] = cases
            entry['_then_target'] = then_target
        elif task_type == 'for':
            each = spec.get('each')
            in_val = spec.get('in')
            at = spec.get('at', None)
            body_block = spec.get('do')
            body_plan, body_name_to_index = compile_block(body_block)
            entry['each'] = each
            entry['in'] = in_val
            entry['at'] = at
            entry['body'] = body_plan
            entry['_then_target'] = then_target
        else:
            entry['_then_target'] = then_target
        entries.append(entry)
    def resolve_target(target, current_index, name_to_index, block_length):
        if target == 'continue':
            next_index = current_index + 1
            if next_index < block_length:
                return next_index
            else:
                return 'end'
        elif target == 'end':
            return 'end'
        else:
            return name_to_index[target]
    for entry in entries:
        if entry['type'] != 'switch':
            entry['next'] = resolve_target(entry.pop('_then_target'), entry['index'], name_to_index, len(entries))
        else:
            cases = entry['cases']
            resolved_cases = []
            for case in cases:
                when = case['when']
                case_then = case.pop('then')
                target = resolve_target(case_then, entry['index'], name_to_index, len(entries))
                resolved_cases.append({'when': when, 'target': target})
            entry['cases'] = resolved_cases
            entry['next'] = resolve_target(entry.pop('_then_target'), entry['index'], name_to_index, len(entries))
    plan_dict = {'tasks': entries}
    cycle_msg = detect_jump_cycle(entries)
    if cycle_msg:
