    if n == 0:
        return None
    visited = [False] * n
    rec_stack = [False] * n
    parent = [-1] * n
    cycles = []
    def dfs(node):
        visited[node] = True
        rec_stack[node] = True
        entry = entries[node]
        if entry['type'] != 'switch' and entry['next'] != 'end' and isinstance(entry['next'], int):
