            for case in entry['cases']:
                target = case['target']
                if target != 'end' and isinstance(target, int):
                    queue.append(target)
            has_default = any(case['when'] is None for case in entry['cases'])
            if not has_default:
                nxt = entry['next']
                if nxt != 'end' and isinstance(nxt, int):
                    queue.append(nxt)
