                            give_up = True
                            break
                    if not give_up:
                        for exc_type in retry_on:
                            if isinstance(exc, exc_type):
                                retry_now = True
                                break

                    if not retry_now or attempt == attempts:
                        # No retry: either not retryable or we've used all attempts
                        raise last_exception

                    # Compute delay for this retry (attempt is the current attempt number, which failed)
                    # The retry index for backoff is the number of retries we've done so far (which is attempt - 1)
                    # but the backoff is called with the retry index (1-based for the first retry).
