    if delay < 0:
        raise ValueError(f"fixed delay must be >= 0, got {delay}")

    def policy(retry_index):
        return delay

    return policy


def exponential(initial, multiplier=2.0, max_delay=None):
    """Backoff policy: initial * multiplier**(retry_index - 1), capped at max_delay."""
    if initial <= 0:
        raise ValueError(f"initial delay must be > 0, got {initial}")
    if multiplier < 1:
        raise ValueError(f"multiplier must be >= 1, got {multiplier}")

    def policy(retry_index):
        delay = initial * multiplier ** (retry_index - 1)
        if max_delay is not None:
            delay = min(delay, max_delay)
        return delay

    return policy


