          sleep=time.sleep, on_retry=None):
    """Decorator factory: retry the wrapped callable on matching exceptions.

    attempts    total call attempts (3 attempts = at most 2 sleeps)
    backoff     callable mapping the 1-based retry index to a delay in seconds
    retry_on    exception types that trigger a retry
    give_up_on  exception types that never retry, even if retry_on matches
    sleep       injectable sleep function (for tests and metrics)
    on_retry    called as on_retry(exc, retry_index, delay) before each sleep
    """
    if attempts < 1:
        raise ValueError(f"attempts must be >= 1, got {attempts}")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except BaseException as exc:
                    if attempt == attempts:
                        raise
                    if isinstance(exc, give_up_on) or not isinstance(exc, retry_on):
                        raise
                    delay = backoff(attempt)
                    if on_retry is not None:
                        on_retry(exc, attempt, delay)
                    sleep(delay)

        return wrapper

    return decorator
