class RoleGraph:
    """Hierarchical roles with deny-overrides semantics.

    Roles inherit grants and denies from their parents, transitively
    (diamonds are fine). A deny anywhere in the resolved closure beats a
    grant anywhere else — including re-grants further down the hierarchy —
    matching the deny-overrides rule Windows ACLs use.
    """

    def __init__(self):
        self._grants = {}
        self._denies = {}
        self._parents = {}

    def add_role(self, name, grants=(), denies=(), inherits=()):
        if not isinstance(name, str) or not name.strip():
            raise ValueError("role name must be a non-blank string")
        if name in self._parents:
            raise ValueError("role already defined: %s" % name)
        parents = tuple(inherits)
        for parent in parents:
            if parent not in self._parents:
                raise KeyError(parent)
        self._grants[name] = frozenset(grants)
        self._denies[name] = frozenset(denies)
        self._parents[name] = parents

    def _closure(self, role):
        """The role plus every ancestor, transitively."""
        if role not in self._parents:
            raise KeyError(role)
        seen = set()
        stack = [role]
        while stack:
            current = stack.pop()
            if current in seen:
                continue
            seen.add(current)
            stack.extend(self._parents[current])
        return seen

    def effective_grants(self, role):
        """Net permissions for one role: inherited grants minus any denies."""
        closure = self._closure(role)
        granted = set()
        denied = set()
        for r in closure:
            granted |= self._grants[r]
            denied |= self._denies[r]
        return frozenset(granted - denied)

    def allowed(self, role_names, perm):
        """True when the combined roles grant perm and none of them deny it."""
        granted = False
        for role in role_names:
