{"name":"Write","arguments":{"content":"export class FlightCache<V> {
  private cache = new Map<keyof any, { value: V; timestamp: number }>();
  private flights = new Map<keyof any, Promise<V>>();
  private invalidatedDuringFlight = new Set<keyof any>();
  private ttlMs: number | undefined;
  private now: () => number;

  constructor(options: { ttlMs?: number; now?: () => number } = {}) {
    this.ttlMs = options.ttlMs;
    this.now = options.now ?? Date.now;
  }

  get(key: string, loader: () => Promise<V>): Promise<V> {
    const now = this.now();
    const cached = this.cache.get(key);
    if (cached !== undefined) {
      if (this.ttlMs === undefined || now - cached.timestamp < this.ttlMs) {
        return Promise.resolve(cached.value);
      }
      // stale: fall through to possibly refetch
    }

    const flight = this.flights.get(key);
    if (flight !== undefined) {
      return flight;
    }

    const flightPromise = loader().then(
      (value) => {
        // success
        if (!this.invalidatedDuringFlight.has(key)) {
          this.cache.set(key, { value, timestamp: this.now() });
        }
        this.invalidatedDuringFlight.delete(key);
        return value;
      },
      (err) => {
        // error: do not cache
        this.invalidatedDuringFlight.delete(key);
        throw err;
      }
    ).finally(() => {
      this.flights.delete(key);
    });

    this.flights.set(key, flightPromise);
    return flightPromise;
  }

  invalidate(key: string): void {
    this.cache.delete(key);
    if (this.flights.has(key)) {
      this.invalidatedDuringFlight.add(key);
    }
  }

  clear(): void {
    this.cache.clear();
    this.flights.clear();
    this.invalidatedDuringFlight.clear();
